namespace Challingo.Core.Puzzles.Games.PathLink;

/// <summary>
/// Connect each pair of same-coloured dots with a path; paths may not cross and must fill the board.
/// Generated by cutting a random Hamiltonian path (backbite moves) into segments, so a solution always
/// exists; any valid solution is accepted. Public: <c>{size, dots:[[a,b],…]}</c> (cell indices);
/// submission: <c>{paths:[[cell,…],…]}</c>, path k joining dots[k] in either direction.
/// </summary>
public sealed class PathLinkGame : IPuzzleGame
{
    private const int MinSegment = 3;

    public string Key => "path-link";
    public int GeneratorVersion => 1;

    public ValueTask<GeneratedPuzzle> GenerateAsync(int seed, int difficulty, CancellationToken ct = default)
    {
        var size = difficulty switch { <= 1 => 5, 2 => 6, 3 => 7, _ => 8 };
        var rng = new Random(seed);
        var path = RandomHamiltonianPath(size, rng);

        // Cut into `colors` segments of at least MinSegment cells, lengths randomised.
        var colors = size;
        var lengths = Enumerable.Repeat(MinSegment, colors).ToArray();
        for (var extra = path.Count - MinSegment * colors; extra > 0; extra--)
            lengths[rng.Next(colors)]++;

        var paths = new List<int[]>();
        var at = 0;
        foreach (var length in lengths)
        {
            paths.Add(path.GetRange(at, length).ToArray());
            at += length;
        }

        return ValueTask.FromResult(new GeneratedPuzzle(
            PuzzleJson.Write(new Public(size, paths.Select(p => new[] { p[0], p[^1] }).ToArray())),
            PuzzleJson.Write(new Secret(paths.ToArray()))));
    }

    public PuzzleVerdict Verify(PuzzleSubmission submission)
    {
        var puzzle = PuzzleJson.Read<Public>(submission.PublicJson);
        var paths = PuzzleJson.TryRead<Submission>(submission.SubmissionJson)?.Paths;
        if (paths is null || paths.Length != puzzle.Dots.Length)
            return PuzzleVerdict.Invalid($"Expected {puzzle.Dots.Length} paths.");

        var cells = puzzle.Size * puzzle.Size;
        var used = new HashSet<int>();
        var dotCells = puzzle.Dots.SelectMany(d => d).ToHashSet();
        for (var k = 0; k < paths.Length; k++)
        {
            var path = paths[k];
            if (path is null || path.Length < 2 || path.Any(i => i < 0 || i >= cells))
                return PuzzleVerdict.Invalid($"Path {k} is malformed.");

            var (a, b) = (puzzle.Dots[k][0], puzzle.Dots[k][1]);
            if (!((path[0] == a && path[^1] == b) || (path[0] == b && path[^1] == a)))
                return PuzzleVerdict.Invalid($"Path {k} must join its two dots.");

            for (var i = 0; i < path.Length; i++)
            {
                if (!used.Add(path[i]))
                    return PuzzleVerdict.Invalid("Paths overlap.");
                if (i > 0 && !Adjacent(path[i - 1], path[i], puzzle.Size))
                    return PuzzleVerdict.Invalid($"Path {k} jumps between cells.");
                if (i > 0 && i < path.Length - 1 && dotCells.Contains(path[i]))
                    return PuzzleVerdict.Invalid($"Path {k} runs through a dot.");
            }
        }

        return used.Count == cells
            ? PuzzleVerdict.Solved()
            : PuzzleVerdict.Incorrect("Fill every cell.");
    }

    private static bool Adjacent(int a, int b, int size)
    {
        int ra = a / size, ca = a % size, rb = b / size, cb = b % size;
        return Math.Abs(ra - rb) + Math.Abs(ca - cb) == 1;
    }

    /// <summary>Starts from a serpentine path and applies random backbite moves to scramble it.</summary>
    public static List<int> RandomHamiltonianPath(int size, Random rng)
    {
        var path = new List<int>(size * size);
        for (var r = 0; r < size; r++)
        for (var c = 0; c < size; c++)
            path.Add(r * size + (r % 2 == 0 ? c : size - 1 - c));

        var steps = size * size * 40;
        for (var s = 0; s < steps; s++)
        {
            if (rng.Next(2) == 0)
                path.Reverse();

            // Backbite at the end of the path: pick a neighbour of the last cell and reverse the tail after it.
            var end = path[^1];
            var neighbours = Neighbours(end, size).Where(n => n != path[^2]).ToList();
            var pick = neighbours[rng.Next(neighbours.Count)];
            var k = path.IndexOf(pick);
            path.Reverse(k + 1, path.Count - k - 1);
        }
        return path;
    }

    private static IEnumerable<int> Neighbours(int i, int size)
    {
        int r = i / size, c = i % size;
        if (r > 0) yield return i - size;
        if (r < size - 1) yield return i + size;
        if (c > 0) yield return i - 1;
        if (c < size - 1) yield return i + 1;
    }

    private sealed record Public(int Size, int[][] Dots);
    private sealed record Secret(int[][] Paths);
    private sealed record Submission(int[][]? Paths);
}
